/* Quick, optional mood/energy/time/location check-in. Auto-saved on every tap. */
const tryitMoods=[['😊','Happy'],['😌','Calm'],['😐','Okay'],['😔','Sad'],['😫','Stressed'],['😴','Tired'],['😩','Overwhelmed'],['😶','Bored']];
const tryitEnergy=['Low','Medium','High'];
const tryitTimes=['10 minutes','30 minutes','1 hour','Several hours'];
const tryitLocations=['Home','Outside','Anywhere'];
let checkin=store.get('checkin',{mood:'',energy:'',time:'',location:''});
function renderCheckinGroup(sel,arr,key,withEmoji){
  $(sel).innerHTML=arr.map(v=>{let label=withEmoji?v[1]:v,emoji=withEmoji?v[0]+' ':'';return `<button data-v="${label}" class="${checkin[key]===label?'selected':''}">${emoji}${label}</button>`}).join('');
  $$(sel+' button').forEach(b=>b.onclick=()=>{checkin[key]=checkin[key]===b.dataset.v?'':b.dataset.v;store.set('checkin',checkin);renderCheckinGroup(sel,arr,key,withEmoji)});
}
renderCheckinGroup('#moodChips',tryitMoods,'mood',true);
renderCheckinGroup('#energyChips',tryitEnergy,'energy',false);
renderCheckinGroup('#timeChips',tryitTimes,'time',false);
renderCheckinGroup('#locationChips',tryitLocations,'location',false);

