/* Favorites, Happy List, Things I Want to Try, and Saved Ideas — reuse the existing modal system. */
modalViews.favorites=function(){
  let cats=['Food','Drinks','Movies','Series','Songs','Artists','Games','Hobbies','Activities','Places','Other'],items=store.get('favorites',[]),filterCat='All',search='';
  function render(){
    let filtered=items.filter(it=>(filterCat==='All'||it.category===filterCat)&&(!search||it.name.toLowerCase().includes(search.toLowerCase())));
    content.innerHTML=`<h2>⭐ My Favorites</h2><p>Keep track of the little things you love.</p><div class="tryit-addrow"><input id="favName" maxlength="60" placeholder="Add a favorite…"><select id="favCat">${cats.map(c=>`<option>${c}</option>`).join('')}</select><button class="primary" id="favAdd">+ Add</button></div><div class="list-manager"><select id="favFilter"><option>All</option>${cats.map(c=>`<option>${c}</option>`).join('')}</select><input id="favSearch" placeholder="Search…" value="${escapeHTML(search)}">${filtered.length?filtered.map(it=>{let i=items.indexOf(it);return `<div class="lm-row"><span>${it.category!=='Other'?escapeHTML(it.category)+' · ':''}${escapeHTML(it.name)}</span><span class="lm-actions"><button data-del="${i}">🗑</button></span></div>`}).join(''):'<p><small>No favorites yet.</small></p>'}</div>`;
    $('#favFilter').value=filterCat;
    $('#favAdd').onclick=()=>{let n=$('#favName').value.trim();if(!n)return;items.push({category:$('#favCat').value,name:n});store.set('favorites',items);render()};
    $('#favFilter').onchange=()=>{filterCat=$('#favFilter').value;render()};
    $('#favSearch').oninput=()=>{search=$('#favSearch').value;render()};
    $$('[data-del]').forEach(b=>b.onclick=()=>{items.splice(+b.dataset.del,1);store.set('favorites',items);render()});
  }
  render();
};
modalViews.happylist=function(){
  content.innerHTML='';
  function render(){content.innerHTML=`<h2>💕 My Happy List</h2><p>Little things that make you happy.</p><div class="tryit-addrow"><input id="hlInput" maxlength="60" placeholder="Coffee, rain, a good song…"><button class="primary" id="hlAdd">+ Add</button></div><div class="list-manager">${happyList.length?happyList.map((v,i)=>`<div class="lm-row"><span>${escapeHTML(v)}</span><span class="lm-actions"><button data-del="${i}">🗑</button></span></div>`).join(''):'<p><small>Nothing here yet.</small></p>'}</div>`;$('#hlAdd').onclick=()=>{let v=$('#hlInput').value.trim();if(!v)return;happyList.push(v);store.set('happyList',happyList);render()};$$('[data-del]').forEach(b=>b.onclick=()=>{happyList.splice(+b.dataset.del,1);store.set('happyList',happyList);render()})}
  render();
};
modalViews.wanttotry=function(){
  function render(){content.innerHTML=`<h2>🌱 Things I Want to Try</h2><p>Little experiences to look forward to.</p><div class="tryit-addrow"><input id="wtInput" maxlength="60" placeholder="Visit Baguio, try pottery…"><button class="primary" id="wtAdd">+ Add</button></div><div class="list-manager">${wantToTry.length?wantToTry.map((it,i)=>`<div class="lm-row ${it.completed?'done':''}"><span>${escapeHTML(it.item)}</span><span class="lm-actions"><button data-done="${i}">${it.completed?'↺':'✓'}</button><button data-del="${i}">🗑</button></span></div>`).join(''):'<p><small>Nothing here yet.</small></p>'}</div>`;$('#wtAdd').onclick=()=>{let v=$('#wtInput').value.trim();if(!v)return;wantToTry.push({item:v,completed:false,created:Date.now()});store.set('wantToTry',wantToTry);render()};$$('[data-done]').forEach(b=>b.onclick=()=>{let i=+b.dataset.done;wantToTry[i].completed=!wantToTry[i].completed;if(wantToTry[i].completed)wantToTry[i].completedDate=Date.now();store.set('wantToTry',wantToTry);render()});$$('[data-del]').forEach(b=>b.onclick=()=>{wantToTry.splice(+b.dataset.del,1);store.set('wantToTry',wantToTry);render()})}
  render();
};
modalViews.savedideas=function(){
  function render(){content.innerHTML=`<h2>💾 Saved Ideas</h2><p>Little suggestions you've saved for later.</p><div class="list-manager">${savedIdeas.length?savedIdeas.map((it,i)=>`<div class="lm-row ${it.status==='completed'?'done':''}"><span>${escapeHTML(it.text)}</span><span class="lm-actions"><button data-try="${i}">Try</button><button data-complete="${i}">✓</button><button data-del="${i}">🗑</button></span></div>`).join(''):'<p><small>Nothing saved yet — try Surprise Me and tap Save it.</small></p>'}</div>`;
    $$('[data-try]').forEach(b=>b.onclick=()=>{let it=savedIdeas[+b.dataset.try],match=suggestionCatalog.find(s=>s.id===it.id);closeModal();if(match?.game)openGame(match.game);else if(match?.modal)openModal(match.modal);else if(match?.page)go(match.page)});
    $$('[data-complete]').forEach(b=>b.onclick=()=>{savedIdeas[+b.dataset.complete].status='completed';store.set('savedIdeas',savedIdeas);render()});
    $$('[data-del]').forEach(b=>b.onclick=()=>{savedIdeas.splice(+b.dataset.del,1);store.set('savedIdeas',savedIdeas);render()});
  }
  render();
};

